  $('#grid-r').innerHTML = `<button type="button" class="pick r" data-i="-1" aria-pressed="false"><span class="q">？</span><span class="pn">おまかせ</span><span class="pa">&nbsp;</span></button>` + D.map((d, i) => pickHTML(d, i, 'r')).join('');
